// Non-recursive binary search
function binarySearch(arr, target) {
  let low = 0;
  let high = arr.length - 1;

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);

    if (arr[mid] === target) {
      return mid; 
    }

    if (arr[mid] < target) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return -1; 
}

// Recursive binary search
function binarySearchRecursive(arr, target, low, high) {
  if (low > high) {
    return -1; 
  }

  const mid = Math.floor((low + high) / 2);

  if (arr[mid] === target) {
    return mid; 
  }

  if (arr[mid] < target) {
    return binarySearchRecursive(arr, target, mid + 1, high); 
  } else {
    return binarySearchRecursive(arr, target, low, mid - 1); 
  }
}

// Example usage
const sortedArray = [2, 5, 8, 12, 16, 20, 25];
console.log('Non-recursive:', binarySearch(sortedArray, 16)); 
// 4
console.log('Recursive:', binarySearchRecursive(sortedArray, 16, 0, sortedArray.length - 1)); 
// 4
console.log('Not found:', binarySearch(sortedArray, 100)); 
// -1
